"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

from heapq import heappop, heappush

Cell = tuple[int, int]  # (row, col)

# Tiles absent from this table, such as '#', cannot be entered.
ENTER_COST = {".": 1, "D": 3, "S": 1, "G": 1}


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    tiles = {
        (row, col): tile
        for row, line in enumerate(grid)
        for col, tile in enumerate(line)
    }
    start = next((cell for cell, tile in tiles.items() if tile == "S"), None)
    if start is None:
        return None

    best_cost = {start: 0}
    came_from: dict[Cell, Cell] = {}
    frontier = [(0, start)]
    while frontier:
        cost, cell = heappop(frontier)
        if cost > best_cost[cell]:
            continue  # stale entry: a cheaper route was queued later
        if tiles[cell] == "G":
            return _rebuild_path(came_from, cell)
        row, col = cell
        for neighbour in ((row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)):
            enter_cost = ENTER_COST.get(tiles.get(neighbour))
            if enter_cost is None:
                continue
            new_cost = cost + enter_cost
            if new_cost < best_cost.get(neighbour, new_cost + 1):
                best_cost[neighbour] = new_cost
                came_from[neighbour] = cell
                heappush(frontier, (new_cost, neighbour))
    return None


def _rebuild_path(came_from: dict[Cell, Cell], goal: Cell) -> list[Cell]:
    path = [goal]
    while path[-1] in came_from:
        path.append(came_from[path[-1]])
    path.reverse()
    return path


