import unittest

from pathfind import find_path


class VisibleTest(unittest.TestCase):
    def test_straight_corridor(self):
        self.assertEqual(find_path(["S..G"]), [(0, 0), (0, 1), (0, 2), (0, 3)])

    def test_detours_around_costly_doors(self):
        self.assertEqual(
            find_path(["SDDG", "...."]),
            [(0, 0), (1, 0), (1, 1), (1, 2), (1, 3), (0, 3)],
        )

    def test_takes_door_when_cheaper(self):
        self.assertEqual(
            find_path(["SDG", ".#.", ".#.", "..."])[1], (0, 1)
        )

    def test_unreachable_returns_none(self):
        self.assertIsNone(find_path(["S#G"]))


if __name__ == "__main__":
    unittest.main()

